require_once __DIR__.'/../config/auth.php';$user=require_role(['owner','kasir']);$pageTitle='Ganti Password';$error='';$message=isset($_SESSION['password_changed'])?'password berhasil diganti.':'';unset($_SESSION['password_changed']);
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$st=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$st->execute([(int)$user['id']]);$hash=(string)$st->fetchColumn();if(!password_verify($current,$hash))$error='password saat ini tidak cocok.';elseif(strlen($new)<12)$error='password baru minimal 12 karakter.';elseif($new!==$confirm)$error='konfirmasi password baru tidak sama.';elseif(password_verify($new,$hash))$error='gunakan password yang berbeda dari password saat ini.';else{$st=$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?');$st->execute([password_hash($new,PASSWORD_DEFAULT),(int)$user['id']]);session_regenerate_id(true);log_activity('change_password','Pengguna mengganti password sendiri');$_SESSION['password_changed']=true;header('Location: '.BASE_URL.'/admin/password.php');exit;}}
require __DIR__.'/../includes/admin-header.php'; ?>
<?php if($message):?><div class="flash flash-ok"><?= h($message) ?></div><?php endif;?><?php if($error):?><div class="flash flash-error"><?= h($error) ?></div><?php endif;?><section class="card p-5 sm:p-8 max-w-xl"><p class="section-kicker">keamanan akun</p><h2 class="font-serif text-3xl mt-2">ganti password</h2><p class="text-sm text-coffee/60 mt-3 leading-6">gunakan password unik minimal 12 karakter. jangan gunakan password yang sama dengan akun lain.</p><form method="post" class="space-y-4 mt-6"><input type="hidden" name="_csrf" value="<?= h(csrf_token()) ?>"><div><label class="field-label">Password saat ini</label><input class="field" type="password" name="current_password" autocomplete="current-password" required></div><div><label class="field-label">Password baru</label><input class="field" type="password" name="new_password" minlength="12" autocomplete="new-password" required></div><div><label class="field-label">Ulangi password baru</label><input class="field" type="password" name="confirm_password" minlength="12" autocomplete="new-password" required></div><button class="btn btn-coffee">Simpan password</button></form></section><?php require __DIR__.'/../includes/admin-footer.php'; ?>
